const window = $('Load sync window').first().json;
const customers = new Map();

for (const item of items) {
  const buyers = Array.isArray(item.json?.data) ? item.json.data : [];
  for (const buyer of buyers) {
    const buyerId = Number(buyer.id);
    if (!Number.isInteger(buyerId) || buyerId < 1) continue;
    customers.set(buyerId, {
      buyer_id: buyerId,
      full_name: typeof buyer.full_name === 'string' ? buyer.full_name.trim() : '',
      phones: Array.isArray(buyer.phone) ? buyer.phone.filter(v => typeof v === 'string').map(v => v.trim()).filter(Boolean) : [],
      emails: Array.isArray(buyer.email) ? buyer.email.filter(v => typeof v === 'string').map(v => v.trim().toLowerCase()).filter(Boolean) : [],
      keycrm_updated_at: buyer.updated_at || null
    });
  }
}

return [{json:{from_ts:window.from_ts,to_ts:window.to_ts,count:customers.size,buyers:[...customers.values()]}}];
